import sqlite3
import json
import urllib.request
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('db-capacity')
INVENTORY_DB_PATH = '/var/lib/dbadmin/inventory.db'
FINANCE_WEBHOOK_URL = 'https://finance.internal.example.com/api/capacity-purchases'

@mcp.tool()
def purchase_provisioned_iops_and_update_instance(instance_identifier: str, additional_iops: int, customer_id: str, price_per_iops_cents: int) -> dict:
    if additional_iops <= 0:
        return {'success': False, 'error': 'additional_iops must be positive'}
    inventory_connection = sqlite3.connect(INVENTORY_DB_PATH)
    inventory_connection.row_factory = sqlite3.Row
    existing_instance_row = inventory_connection.execute('SELECT identifier, provisioned_iops FROM db_instances WHERE identifier = ?', (instance_identifier,)).fetchone()
    if existing_instance_row is None:
        inventory_connection.close()
        return {'success': False, 'error': 'instance not found in inventory'}
    current_provisioned_iops = existing_instance_row['provisioned_iops'] or 0
    new_provisioned_iops_total = current_provisioned_iops + additional_iops
    total_charge_amount_cents = additional_iops * price_per_iops_cents
    try:
        payment_charge_result = stripe.PaymentIntent.create(amount=total_charge_amount_cents, currency='usd', customer=customer_id, confirm=True, off_session=True, description='Provisioned IOPS for %s' % instance_identifier)
    except stripe.error.StripeError as payment_error:
        inventory_connection.close()
        return {'success': False, 'error': str(payment_error)}
    if payment_charge_result['status'] != 'succeeded':
        inventory_connection.close()
        return {'success': False, 'error': 'payment status: %s' % payment_charge_result['status'], 'charge_id': payment_charge_result['id']}
    with inventory_connection:
        inventory_connection.execute('UPDATE db_instances SET provisioned_iops = ? WHERE identifier = ?', (new_provisioned_iops_total, instance_identifier))
    inventory_connection.close()
    try:
        notification_payload = json.dumps({'instance': instance_identifier, 'customer_id': customer_id, 'charge_id': payment_charge_result['id'], 'amount_cents': total_charge_amount_cents, 'additional_iops': additional_iops, 'new_iops': new_provisioned_iops_total}).encode('utf-8')
        notification_request = urllib.request.Request(FINANCE_WEBHOOK_URL, data=notification_payload, headers={'Content-Type': 'application/json'}, method='POST')
        urllib.request.urlopen(notification_request, timeout=5)
    except Exception:
        pass
    return {'success': True, 'charge_id': payment_charge_result['id'], 'amount_cents': total_charge_amount_cents, 'previous_iops': current_provisioned_iops, 'new_iops': new_provisioned_iops_total}
